sys_ux_client_script.script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var requestBody = request.body.nextEntry();
    var email = requestBody.email;
    var firstName = requestBody.first_name;
    var lastName = requestBody.last_name;

    if (!email) {
        return new sn_ws_err.BadRequestError("Email is required.");
    }

    var grUserCheck = new GlideRecord('sys_user');
    if (grUserCheck.get('email', email)) {
        return new sn_ws_err.ConflictError("A user with this email already exists.");
    }

    var grUser = new GlideRecord('sys_user');
    grUser.initialize();
    grUser.user_name = email;
    grUser.email = email;
    grUser.first_name = firstName;
    grUser.last_name = lastName;

    // EXPLICIT STAGING OVERRIDE
    grUser.active = false;            // Set boolean
    grUser.setDisplayValue('active', 'false'); 
    grUser.locked_out = true;         // Lock account until verification

    var userSysId = grUser.insert();

    if (userSysId) {
        // Assign Default Traveler Role[cite: 1]
        var grRole = new GlideRecord('sys_user_has_role');
        grRole.initialize();
        grRole.user = userSysId;

        var grRoleRef = new GlideRecord('sys_user_role');
        if (grRoleRef.get('name', 'snc_external')) { 
            grRole.role = grRoleRef.getUniqueValue();
            grRole.insert();
        }

        // Trigger Email Verification Event[cite: 1]
        gs.eventQueue('custom.traveler.password_reset', grUser, userSysId, email);

        response.setBody({
            status: "success",
            message: "User registered successfully. Verification email sent.",
            sys_id: userSysId
        });
        response.setStatus(201);
    } else {
        return new sn_ws_err.ServerError("Failed to create user record.");
    }

})(request, response);
